-- WASSCE CRS Questions - 2024 (50 questions)
INSERT OR REPLACE INTO questions (id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, options, correct_answer, explanation, difficulty, marks, question_number) VALUES
-- Creation and Early History (Questions 1-10)
('q_crs_2024_001', 'subj_wassce_crs', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_crs_2024_1', 'According to the Book of Genesis, on which day did God create man?', 'multiple_choice', '["A. Fourth day", "B. Fifth day", "C. Sixth day", "D. Seventh day"]', 'C', 'According to Genesis 1:26-27, God created man on the sixth day of creation, after creating animals and before resting on the seventh day.', 'easy', 1, 1),
('q_crs_2024_002', 'subj_wassce_crs', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_crs_2024_1', 'What was the name of the garden where Adam and Eve were placed?', 'multiple_choice', '["A. Garden of Gethsemane", "B. Garden of Eden", "C. Garden of Paradise", "D. Garden of Galilee"]', 'B', 'According to Genesis 2:8, God planted a garden in Eden and placed Adam there. Eden means "delight" or "pleasure."', 'easy', 1, 2),
('q_crs_2024_003', 'subj_wassce_crs', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_crs_2024_1', 'Which of the following was NOT a consequence of the Fall of Man?', 'multiple_choice', '["A. Death entered the world", "B. Painful childbirth for women", "C. Man would live forever", "D. Man would work hard for food"]', 'C', 'The Fall resulted in mortality, not immortality. Man was expelled from Eden to prevent him from eating from the Tree of Life and living forever (Genesis 3:22-24).', 'medium', 1, 3),
('q_crs_2024_004', 'subj_wassce_crs', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_crs_2024_1', 'Who was the first murderer mentioned in the Bible?', 'multiple_choice', '["A. Abel", "B. Seth", "C. Cain", "D. Lamech"]', 'C', 'Cain killed his brother Abel out of jealousy when God accepted Abel''s offering but rejected Cain''s (Genesis 4:8).', 'easy', 1, 4),
('q_crs_2024_005', 'subj_wassce_crs', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_crs_2024_1', 'According to Genesis, how old was Noah when the flood came?', 'multiple_choice', '["A. 500 years", "B. 600 years", "C. 700 years", "D. 800 years"]', 'B', 'Genesis 7:6 states that Noah was 600 years old when the floodwaters came upon the earth.', 'medium', 1, 5),
('q_crs_2024_006', 'subj_wassce_crs', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_crs_2024_1', 'What was the sign of the covenant between God and Noah?', 'multiple_choice', '["A. Circumcision", "B. Rainbow", "C. Dove", "D. Olive branch"]', 'B', 'The rainbow was the sign of God''s covenant with Noah, promising never again to destroy the earth with a flood (Genesis 9:12-17).', 'easy', 1, 6),
('q_crs_2024_007', 'subj_wassce_crs', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_crs_2024_1', 'The Tower of Babel incident resulted in:', 'multiple_choice', '["A. A great flood", "B. Confusion of languages", "C. Death of the builders", "D. An earthquake"]', 'B', 'God confused the language of the people building the Tower of Babel, causing them to scatter across the earth (Genesis 11:7-9).', 'easy', 1, 7),
('q_crs_2024_008', 'subj_wassce_crs', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_crs_2024_1', 'What was the original name of Abraham?', 'multiple_choice', '["A. Adam", "B. Abram", "C. Isaac", "D. Jacob"]', 'B', 'Abraham was originally named Abram. God changed his name to Abraham, meaning "father of many nations" (Genesis 17:5).', 'easy', 1, 8),
('q_crs_2024_009', 'subj_wassce_crs', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_crs_2024_1', 'God tested Abraham''s faith by asking him to sacrifice:', 'multiple_choice', '["A. Ishmael", "B. Isaac", "C. A lamb", "D. His wife"]', 'B', 'God tested Abraham by asking him to sacrifice his son Isaac on Mount Moriah (Genesis 22). God provided a ram as a substitute.', 'easy', 1, 9),
('q_crs_2024_010', 'subj_wassce_crs', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_crs_2024_1', 'Who sold his birthright for a bowl of stew?', 'multiple_choice', '["A. Jacob", "B. Esau", "C. Joseph", "D. Reuben"]', 'B', 'Esau sold his birthright to his younger brother Jacob for a bowl of red lentil stew (Genesis 25:29-34).', 'easy', 1, 10),

-- Patriarchs and Exodus (Questions 11-20)
('q_crs_2024_011', 'subj_wassce_crs', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_crs_2024_1', 'Joseph was sold into slavery by his brothers for:', 'multiple_choice', '["A. Ten pieces of silver", "B. Twenty pieces of silver", "C. Thirty pieces of silver", "D. Forty pieces of silver"]', 'B', 'Joseph''s brothers sold him to Midianite merchants for twenty pieces of silver (Genesis 37:28).', 'medium', 1, 11),
('q_crs_2024_012', 'subj_wassce_crs', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_crs_2024_1', 'What was Moses'' offense that prevented him from entering the Promised Land?', 'multiple_choice', '["A. Making a golden calf", "B. Striking the rock instead of speaking to it", "C. Marrying a foreigner", "D. Killing an Egyptian"]', 'B', 'God told Moses to speak to the rock, but Moses struck it twice in anger, showing distrust in God''s word (Numbers 20:8-12).', 'medium', 1, 12),
('q_crs_2024_013', 'subj_wassce_crs', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_crs_2024_1', 'How many plagues did God send upon Egypt?', 'multiple_choice', '["A. Seven", "B. Eight", "C. Ten", "D. Twelve"]', 'C', 'God sent ten plagues upon Egypt to compel Pharaoh to release the Israelites from slavery (Exodus 7-12).', 'easy', 1, 13),
('q_crs_2024_014', 'subj_wassce_crs', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_crs_2024_1', 'The Passover commemorates:', 'multiple_choice', '["A. The crossing of the Red Sea", "B. The death angel passing over Israelite homes", "C. The giving of the Ten Commandments", "D. The manna in the wilderness"]', 'B', 'The Passover commemorates the night when the death angel passed over Israelite homes marked with lamb''s blood, sparing their firstborn (Exodus 12).', 'easy', 1, 14),
('q_crs_2024_015', 'subj_wassce_crs', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_crs_2024_1', 'The Ten Commandments were given to Moses on:', 'multiple_choice', '["A. Mount Carmel", "B. Mount Sinai", "C. Mount of Olives", "D. Mount Zion"]', 'B', 'God gave Moses the Ten Commandments on Mount Sinai (Exodus 19-20).', 'easy', 1, 15),
('q_crs_2024_016', 'subj_wassce_crs', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_crs_2024_1', 'Which commandment states "You shall not commit adultery"?', 'multiple_choice', '["A. Fifth Commandment", "B. Sixth Commandment", "C. Seventh Commandment", "D. Eighth Commandment"]', 'C', 'The Seventh Commandment prohibits adultery (Exodus 20:14).', 'medium', 1, 16),
('q_crs_2024_017', 'subj_wassce_crs', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_crs_2024_1', 'While Moses was on Mount Sinai, the Israelites made:', 'multiple_choice', '["A. A golden calf", "B. A bronze serpent", "C. A golden temple", "D. A silver chariot"]', 'A', 'While Moses was receiving the commandments, Aaron made a golden calf idol for the Israelites to worship (Exodus 32).', 'easy', 1, 17),
('q_crs_2024_018', 'subj_wassce_crs', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_crs_2024_1', 'How many spies did Moses send to explore Canaan?', 'multiple_choice', '["A. Ten", "B. Twelve", "C. Fourteen", "D. Sixteen"]', 'B', 'Moses sent twelve spies, one from each tribe of Israel, to explore the land of Canaan (Numbers 13:1-2).', 'easy', 1, 18),
('q_crs_2024_019', 'subj_wassce_crs', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_crs_2024_1', 'Which two spies brought a positive report about Canaan?', 'multiple_choice', '["A. Moses and Aaron", "B. Joshua and Caleb", "C. Abraham and Isaac", "D. David and Jonathan"]', 'B', 'Only Joshua and Caleb believed Israel could conquer Canaan with God''s help, while the other ten spies were fearful (Numbers 14:6-9).', 'easy', 1, 19),
('q_crs_2024_020', 'subj_wassce_crs', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_crs_2024_1', 'The Israelites wandered in the wilderness for:', 'multiple_choice', '["A. 10 years", "B. 20 years", "C. 40 years", "D. 50 years"]', 'C', 'Due to their unbelief, the Israelites wandered in the wilderness for 40 years until that generation died out (Numbers 14:33-34).', 'easy', 1, 20),

-- Judges and Kings (Questions 21-30)
('q_crs_2024_021', 'subj_wassce_crs', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_crs_2024_1', 'Who was the last judge of Israel before the monarchy?', 'multiple_choice', '["A. Gideon", "B. Samson", "C. Samuel", "D. Eli"]', 'C', 'Samuel was the last judge who also anointed the first two kings of Israel, Saul and David.', 'medium', 1, 21),
('q_crs_2024_022', 'subj_wassce_crs', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_crs_2024_1', 'What was the source of Samson''s strength?', 'multiple_choice', '["A. His muscles", "B. His hair", "C. His diet", "D. His armor"]', 'B', 'Samson''s strength came from his Nazirite vow, symbolized by his uncut hair. When Delilah cut it, his strength left him (Judges 16).', 'easy', 1, 22),
('q_crs_2024_023', 'subj_wassce_crs', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_crs_2024_1', 'Who was the first king of Israel?', 'multiple_choice', '["A. David", "B. Solomon", "C. Saul", "D. Samuel"]', 'C', 'Saul was the first king of Israel, anointed by Samuel at the people''s request (1 Samuel 9-10).', 'easy', 1, 23),
('q_crs_2024_024', 'subj_wassce_crs', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_crs_2024_1', 'David killed the giant Goliath with:', 'multiple_choice', '["A. A sword", "B. A spear", "C. A sling and stone", "D. A bow and arrow"]', 'C', 'David killed Goliath with a sling and a single stone, which struck the giant on the forehead (1 Samuel 17:49-50).', 'easy', 1, 24),
('q_crs_2024_025', 'subj_wassce_crs', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_crs_2024_1', 'Which prophet confronted David about his sin with Bathsheba?', 'multiple_choice', '["A. Elijah", "B. Elisha", "C. Nathan", "D. Isaiah"]', 'C', 'Prophet Nathan confronted King David with a parable about a rich man stealing a poor man''s lamb (2 Samuel 12).', 'medium', 1, 25),
('q_crs_2024_026', 'subj_wassce_crs', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_crs_2024_1', 'Solomon asked God for:', 'multiple_choice', '["A. Long life", "B. Great wealth", "C. Victory over enemies", "D. Wisdom to lead Israel"]', 'D', 'When God offered Solomon anything, he asked for wisdom to govern the people. God was pleased and gave him wisdom plus riches and honor (1 Kings 3:9-13).', 'easy', 1, 26),
('q_crs_2024_027', 'subj_wassce_crs', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_crs_2024_1', 'The kingdom of Israel divided after the death of:', 'multiple_choice', '["A. David", "B. Solomon", "C. Rehoboam", "D. Jeroboam"]', 'B', 'After Solomon''s death, his son Rehoboam''s harsh rule caused the kingdom to split into Israel (North) and Judah (South) (1 Kings 12).', 'medium', 1, 27),
('q_crs_2024_028', 'subj_wassce_crs', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_crs_2024_1', 'Elijah challenged the prophets of Baal on:', 'multiple_choice', '["A. Mount Sinai", "B. Mount Carmel", "C. Mount Zion", "D. Mount Hermon"]', 'B', 'Elijah challenged and defeated the prophets of Baal in a dramatic contest on Mount Carmel (1 Kings 18).', 'medium', 1, 28),
('q_crs_2024_029', 'subj_wassce_crs', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_crs_2024_1', 'How did Elijah leave the earth?', 'multiple_choice', '["A. He died of old age", "B. He was killed by enemies", "C. He was taken up in a whirlwind", "D. He drowned in the Jordan"]', 'C', 'Elijah was taken up to heaven in a whirlwind with a chariot and horses of fire (2 Kings 2:11).', 'easy', 1, 29),
('q_crs_2024_030', 'subj_wassce_crs', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_crs_2024_1', 'Who succeeded Elijah as prophet?', 'multiple_choice', '["A. Isaiah", "B. Jeremiah", "C. Elisha", "D. Amos"]', 'C', 'Elisha, who had served as Elijah''s attendant, received a double portion of his spirit and continued his prophetic ministry (2 Kings 2:9-15).', 'easy', 1, 30),

-- Prophets and Exile (Questions 31-35)
('q_crs_2024_031', 'subj_wassce_crs', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_crs_2024_1', 'Which empire conquered the Northern Kingdom of Israel?', 'multiple_choice', '["A. Babylon", "B. Assyria", "C. Persia", "D. Egypt"]', 'B', 'The Assyrian Empire conquered the Northern Kingdom of Israel in 722 BC and deported its people (2 Kings 17).', 'medium', 1, 31),
('q_crs_2024_032', 'subj_wassce_crs', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_crs_2024_1', 'The prophet who spent three days in the belly of a great fish was:', 'multiple_choice', '["A. Jeremiah", "B. Jonah", "C. Joel", "D. Amos"]', 'B', 'Jonah was swallowed by a great fish for three days when he tried to flee from God''s command to preach to Nineveh (Jonah 1-2).', 'easy', 1, 32),
('q_crs_2024_033', 'subj_wassce_crs', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_crs_2024_1', 'Isaiah prophesied that the Messiah would be born of:', 'multiple_choice', '["A. A princess", "B. A virgin", "C. A prophet", "D. A widow"]', 'B', 'Isaiah 7:14 prophesied that a virgin would conceive and bear a son called Immanuel, fulfilled in Jesus Christ.', 'easy', 1, 33),
('q_crs_2024_034', 'subj_wassce_crs', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_crs_2024_1', 'Daniel was thrown into the lions'' den for:', 'multiple_choice', '["A. Stealing from the king", "B. Praying to God", "C. Plotting against Babylon", "D. Refusing to work"]', 'B', 'Daniel was thrown into the lions'' den because he continued praying to God despite a decree forbidding prayer to anyone except King Darius (Daniel 6).', 'easy', 1, 34),
('q_crs_2024_035', 'subj_wassce_crs', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_crs_2024_1', 'The three Hebrew boys who were thrown into the fiery furnace were:', 'multiple_choice', '["A. Peter, James, and John", "B. Shadrach, Meshach, and Abednego", "C. Abraham, Isaac, and Jacob", "D. David, Solomon, and Rehoboam"]', 'B', 'Shadrach, Meshach, and Abednego refused to worship Nebuchadnezzar''s golden image and were thrown into a fiery furnace (Daniel 3).', 'easy', 1, 35),

-- New Testament: Life of Jesus (Questions 36-45)
('q_crs_2024_036', 'subj_wassce_crs', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_crs_2024_1', 'Jesus was born in:', 'multiple_choice', '["A. Nazareth", "B. Jerusalem", "C. Bethlehem", "D. Galilee"]', 'C', 'Jesus was born in Bethlehem of Judea, as prophesied by Micah and recorded in Matthew 2:1 and Luke 2:4-7.', 'easy', 1, 36),
('q_crs_2024_037', 'subj_wassce_crs', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_crs_2024_1', 'Who baptized Jesus in the River Jordan?', 'multiple_choice', '["A. Peter", "B. Andrew", "C. John the Baptist", "D. James"]', 'C', 'John the Baptist baptized Jesus in the River Jordan, where the Spirit descended like a dove and God''s voice confirmed Jesus as His Son (Matthew 3:13-17).', 'easy', 1, 37),
('q_crs_2024_038', 'subj_wassce_crs', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_crs_2024_1', 'Jesus fasted in the wilderness for:', 'multiple_choice', '["A. Seven days", "B. Fourteen days", "C. Thirty days", "D. Forty days"]', 'D', 'Jesus fasted for forty days and nights in the wilderness before being tempted by Satan (Matthew 4:1-2).', 'easy', 1, 38),
('q_crs_2024_039', 'subj_wassce_crs', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_crs_2024_1', 'Jesus'' first miracle was:', 'multiple_choice', '["A. Healing a blind man", "B. Feeding 5000", "C. Turning water into wine", "D. Walking on water"]', 'C', 'Jesus'' first miracle was turning water into wine at a wedding in Cana of Galilee (John 2:1-11).', 'easy', 1, 39),
('q_crs_2024_040', 'subj_wassce_crs', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_crs_2024_1', 'How many disciples did Jesus choose?', 'multiple_choice', '["A. Ten", "B. Twelve", "C. Fourteen", "D. Sixteen"]', 'B', 'Jesus chose twelve disciples (apostles) to follow him and continue his ministry (Matthew 10:1-4).', 'easy', 1, 40),
('q_crs_2024_041', 'subj_wassce_crs', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_crs_2024_1', 'The Beatitudes are found in:', 'multiple_choice', '["A. The Lord''s Prayer", "B. The Sermon on the Mount", "C. The Last Supper", "D. The Parable of the Sower"]', 'B', 'The Beatitudes are the opening statements of Jesus'' Sermon on the Mount (Matthew 5:3-12).', 'medium', 1, 41),
('q_crs_2024_042', 'subj_wassce_crs', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_crs_2024_1', 'In the Parable of the Prodigal Son, the younger son wasted his inheritance on:', 'multiple_choice', '["A. Building a house", "B. Wild living", "C. Buying sheep", "D. Helping the poor"]', 'B', 'The younger son squandered his wealth on wild living before returning home repentant (Luke 15:13).', 'easy', 1, 42),
('q_crs_2024_043', 'subj_wassce_crs', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_crs_2024_1', 'Jesus raised Lazarus from the dead after how many days?', 'multiple_choice', '["A. One day", "B. Two days", "C. Three days", "D. Four days"]', 'D', 'Lazarus had been in the tomb for four days when Jesus raised him from the dead (John 11:17, 39).', 'medium', 1, 43),
('q_crs_2024_044', 'subj_wassce_crs', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_crs_2024_1', 'Who betrayed Jesus to the Jewish authorities?', 'multiple_choice', '["A. Peter", "B. Thomas", "C. Judas Iscariot", "D. Matthew"]', 'C', 'Judas Iscariot betrayed Jesus for thirty pieces of silver (Matthew 26:14-16, 47-50).', 'easy', 1, 44),
('q_crs_2024_045', 'subj_wassce_crs', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_crs_2024_1', 'Jesus was crucified at a place called:', 'multiple_choice', '["A. Gethsemane", "B. Bethany", "C. Golgotha", "D. Bethlehem"]', 'C', 'Jesus was crucified at Golgotha, which means "Place of the Skull" (Matthew 27:33, John 19:17).', 'easy', 1, 45),

-- Early Church and Epistles (Questions 46-50)
('q_crs_2024_046', 'subj_wassce_crs', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_crs_2024_1', 'The Holy Spirit came upon the disciples on:', 'multiple_choice', '["A. Easter", "B. Passover", "C. Pentecost", "D. Christmas"]', 'C', 'The Holy Spirit came upon the disciples on the day of Pentecost, fifty days after Passover (Acts 2).', 'easy', 1, 46),
('q_crs_2024_047', 'subj_wassce_crs', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_crs_2024_1', 'Who was known as the "Apostle to the Gentiles"?', 'multiple_choice', '["A. Peter", "B. James", "C. Paul", "D. John"]', 'C', 'Paul (formerly Saul) was called the Apostle to the Gentiles because of his missionary work among non-Jews (Romans 11:13).', 'easy', 1, 47),
('q_crs_2024_048', 'subj_wassce_crs', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_crs_2024_1', 'Saul was converted on the road to:', 'multiple_choice', '["A. Jerusalem", "B. Damascus", "C. Rome", "D. Athens"]', 'B', 'Saul was traveling to Damascus to persecute Christians when Jesus appeared to him and he was converted (Acts 9:1-9).', 'easy', 1, 48),
('q_crs_2024_049', 'subj_wassce_crs', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_crs_2024_1', 'According to Paul, the greatest of faith, hope, and love is:', 'multiple_choice', '["A. Faith", "B. Hope", "C. Love", "D. All are equal"]', 'C', 'In 1 Corinthians 13:13, Paul states that the greatest of these three virtues is love (charity).', 'easy', 1, 49),
('q_crs_2024_050', 'subj_wassce_crs', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_crs_2024_1', 'The fruits of the Spirit include all EXCEPT:', 'multiple_choice', '["A. Love and joy", "B. Peace and patience", "C. Anger and jealousy", "D. Self-control and gentleness"]', 'C', 'The fruits of the Spirit in Galatians 5:22-23 are love, joy, peace, patience, kindness, goodness, faithfulness, gentleness, and self-control. Anger and jealousy are works of the flesh.', 'medium', 1, 50),

-- WASSCE CRS Questions - 2023 (50 questions)
-- Creation and Fall (Questions 1-10)
('q_crs_2023_001', 'subj_wassce_crs', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_crs_2023_1', 'In the beginning, God created:', 'multiple_choice', '["A. Man and woman", "B. The heavens and the earth", "C. Light and darkness", "D. Plants and animals"]', 'B', 'Genesis 1:1 states "In the beginning, God created the heavens and the earth."', 'easy', 1, 1),
('q_crs_2023_002', 'subj_wassce_crs', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_crs_2023_1', 'Man was created from:', 'multiple_choice', '["A. Water", "B. Fire", "C. Dust of the ground", "D. Air"]', 'C', 'According to Genesis 2:7, God formed man from the dust of the ground and breathed life into his nostrils.', 'easy', 1, 2),
('q_crs_2023_003', 'subj_wassce_crs', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_crs_2023_1', 'The tree that Adam and Eve were forbidden to eat from was called:', 'multiple_choice', '["A. Tree of Life", "B. Tree of Knowledge of Good and Evil", "C. Tree of Wisdom", "D. Tree of Paradise"]', 'B', 'God forbade Adam and Eve from eating from the Tree of Knowledge of Good and Evil (Genesis 2:17).', 'easy', 1, 3),
('q_crs_2023_004', 'subj_wassce_crs', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_crs_2023_1', 'The serpent was cursed to:', 'multiple_choice', '["A. Fly in the air", "B. Crawl on its belly", "C. Live in water", "D. Lose its scales"]', 'B', 'As punishment for deceiving Eve, the serpent was cursed to crawl on its belly and eat dust (Genesis 3:14).', 'easy', 1, 4),
('q_crs_2023_005', 'subj_wassce_crs', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_crs_2023_1', 'What did God place at the east of the Garden of Eden after expelling Adam and Eve?', 'multiple_choice', '["A. Angels with swords", "B. Cherubim with a flaming sword", "C. A wall of fire", "D. A river"]', 'B', 'God placed cherubim with a flaming sword to guard the way to the Tree of Life (Genesis 3:24).', 'medium', 1, 5),
('q_crs_2023_006', 'subj_wassce_crs', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_crs_2023_1', 'Abel was a:', 'multiple_choice', '["A. Farmer", "B. Shepherd", "C. Hunter", "D. Builder"]', 'B', 'Abel was a keeper of sheep (shepherd) while his brother Cain was a tiller of the ground (Genesis 4:2).', 'easy', 1, 6),
('q_crs_2023_007', 'subj_wassce_crs', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_crs_2023_1', 'What mark did God put on Cain?', 'multiple_choice', '["A. A mark of death", "B. A mark of protection", "C. A mark of slavery", "D. A mark of honor"]', 'B', 'God put a protective mark on Cain so that no one who found him would kill him (Genesis 4:15).', 'medium', 1, 7),
('q_crs_2023_008', 'subj_wassce_crs', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_crs_2023_1', 'Who walked with God and was taken to heaven without dying?', 'multiple_choice', '["A. Noah", "B. Enoch", "C. Abraham", "D. Moses"]', 'B', 'Enoch walked faithfully with God, and God took him away so that he did not experience death (Genesis 5:24, Hebrews 11:5).', 'medium', 1, 8),
('q_crs_2023_009', 'subj_wassce_crs', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_crs_2023_1', 'How many of each clean animal did Noah take into the ark?', 'multiple_choice', '["A. Two", "B. Seven", "C. Twelve", "D. Fourteen"]', 'B', 'Noah was instructed to take seven pairs of every clean animal and one pair of every unclean animal (Genesis 7:2).', 'medium', 1, 9),
('q_crs_2023_010', 'subj_wassce_crs', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_crs_2023_1', 'What did Noah send out first to check if the waters had receded?', 'multiple_choice', '["A. A dove", "B. A raven", "C. A sparrow", "D. An eagle"]', 'B', 'Noah first sent out a raven, then later sent out a dove (Genesis 8:7-8).', 'medium', 1, 10),

-- Patriarchs and Covenant (Questions 11-20)
('q_crs_2023_011', 'subj_wassce_crs', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_crs_2023_1', 'God called Abraham from:', 'multiple_choice', '["A. Egypt", "B. Canaan", "C. Ur of the Chaldees", "D. Babylon"]', 'C', 'God called Abraham (then Abram) from Ur of the Chaldees to go to a land He would show him (Genesis 11:31, Acts 7:2-4).', 'medium', 1, 11),
('q_crs_2023_012', 'subj_wassce_crs', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_crs_2023_1', 'The sign of God''s covenant with Abraham was:', 'multiple_choice', '["A. Rainbow", "B. Circumcision", "C. Sabbath", "D. Baptism"]', 'B', 'Circumcision was the sign of the covenant between God and Abraham and his descendants (Genesis 17:10-11).', 'easy', 1, 12),
('q_crs_2023_013', 'subj_wassce_crs', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_crs_2023_1', 'Abraham''s wife Sarah gave birth to Isaac when she was:', 'multiple_choice', '["A. 70 years old", "B. 80 years old", "C. 90 years old", "D. 100 years old"]', 'C', 'Sarah gave birth to Isaac when she was 90 years old, as God had promised (Genesis 17:17, 21:2-5).', 'medium', 1, 13),
('q_crs_2023_014', 'subj_wassce_crs', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_crs_2023_1', 'Isaac''s wife was:', 'multiple_choice', '["A. Rachel", "B. Leah", "C. Rebekah", "D. Sarah"]', 'C', 'Rebekah was Isaac''s wife, found for him by Abraham''s servant at a well (Genesis 24).', 'easy', 1, 14),
('q_crs_2023_015', 'subj_wassce_crs', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_crs_2023_1', 'Jacob''s name was changed to:', 'multiple_choice', '["A. Abraham", "B. Isaac", "C. Israel", "D. Joseph"]', 'C', 'After wrestling with the angel, Jacob''s name was changed to Israel, meaning "he who struggles with God" (Genesis 32:28).', 'easy', 1, 15),
('q_crs_2023_016', 'subj_wassce_crs', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_crs_2023_1', 'How many sons did Jacob have?', 'multiple_choice', '["A. Ten", "B. Twelve", "C. Fourteen", "D. Sixteen"]', 'B', 'Jacob had twelve sons who became the ancestors of the twelve tribes of Israel.', 'easy', 1, 16),
('q_crs_2023_017', 'subj_wassce_crs', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_crs_2023_1', 'Joseph interpreted Pharaoh''s dream about:', 'multiple_choice', '["A. Ten plagues", "B. Seven years of plenty and seven years of famine", "C. The Exodus", "D. A great war"]', 'B', 'Joseph interpreted Pharaoh''s dreams as meaning seven years of abundance followed by seven years of severe famine (Genesis 41:25-32).', 'easy', 1, 17),
('q_crs_2023_018', 'subj_wassce_crs', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_crs_2023_1', 'Where did the Israelites live in Egypt?', 'multiple_choice', '["A. Canaan", "B. Goshen", "C. Sinai", "D. Memphis"]', 'B', 'The Israelites settled in the land of Goshen in Egypt (Genesis 47:6).', 'medium', 1, 18),
('q_crs_2023_019', 'subj_wassce_crs', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_crs_2023_1', 'Who found baby Moses in the Nile River?', 'multiple_choice', '["A. A slave girl", "B. Pharaoh''s daughter", "C. Moses'' mother", "D. Miriam"]', 'B', 'Pharaoh''s daughter found baby Moses among the reeds of the Nile and adopted him (Exodus 2:5-10).', 'easy', 1, 19),
('q_crs_2023_020', 'subj_wassce_crs', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_crs_2023_1', 'God appeared to Moses in:', 'multiple_choice', '["A. A burning bush", "B. A cloud", "C. A dream", "D. A temple"]', 'A', 'God appeared to Moses in a burning bush that was not consumed by fire at Mount Horeb (Exodus 3:2-4).', 'easy', 1, 20),

-- Exodus and Wilderness (Questions 21-30)
('q_crs_2023_021', 'subj_wassce_crs', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_crs_2023_1', 'The last of the ten plagues was:', 'multiple_choice', '["A. Locusts", "B. Darkness", "C. Death of firstborn", "D. Boils"]', 'C', 'The tenth and final plague was the death of all firstborn in Egypt who were not protected by the lamb''s blood (Exodus 12:29).', 'easy', 1, 21),
('q_crs_2023_022', 'subj_wassce_crs', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_crs_2023_1', 'What did God use to guide the Israelites by day?', 'multiple_choice', '["A. A pillar of fire", "B. A pillar of cloud", "C. An angel", "D. A star"]', 'B', 'God led the Israelites by a pillar of cloud by day and a pillar of fire by night (Exodus 13:21-22).', 'easy', 1, 22),
('q_crs_2023_023', 'subj_wassce_crs', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_crs_2023_1', 'What food did God provide for the Israelites in the wilderness?', 'multiple_choice', '["A. Fish", "B. Bread only", "C. Manna and quail", "D. Fruits"]', 'C', 'God provided manna (bread from heaven) each morning and quail for meat in the evening (Exodus 16).', 'easy', 1, 23),
('q_crs_2023_024', 'subj_wassce_crs', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_crs_2023_1', 'The first commandment states:', 'multiple_choice', '["A. You shall not kill", "B. You shall not steal", "C. You shall have no other gods before me", "D. Honor your father and mother"]', 'C', 'The first commandment is "You shall have no other gods before me" (Exodus 20:3).', 'easy', 1, 24),
('q_crs_2023_025', 'subj_wassce_crs', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_crs_2023_1', 'The fourth commandment requires:', 'multiple_choice', '["A. Not to kill", "B. Not to steal", "C. To keep the Sabbath holy", "D. To honor parents"]', 'C', 'The fourth commandment states "Remember the Sabbath day, to keep it holy" (Exodus 20:8).', 'easy', 1, 25),
('q_crs_2023_026', 'subj_wassce_crs', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_crs_2023_1', 'The Ark of the Covenant contained all EXCEPT:', 'multiple_choice', '["A. The tablets of the Ten Commandments", "B. Aaron''s rod that budded", "C. A pot of manna", "D. The bronze serpent"]', 'D', 'The Ark contained the tablets of the commandments, Aaron''s rod, and a pot of manna (Hebrews 9:4). The bronze serpent was made separately.', 'medium', 1, 26),
('q_crs_2023_027', 'subj_wassce_crs', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_crs_2023_1', 'Who led the Israelites across the Jordan into the Promised Land?', 'multiple_choice', '["A. Moses", "B. Aaron", "C. Joshua", "D. Caleb"]', 'C', 'Joshua succeeded Moses and led the Israelites across the Jordan River into Canaan (Joshua 3).', 'easy', 1, 27),
('q_crs_2023_028', 'subj_wassce_crs', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_crs_2023_1', 'The walls of Jericho fell after the Israelites:', 'multiple_choice', '["A. Attacked with weapons", "B. Used battering rams", "C. Marched around and shouted", "D. Prayed for seven days"]', 'C', 'The walls of Jericho fell after the Israelites marched around the city for seven days and shouted (Joshua 6).', 'easy', 1, 28),
('q_crs_2023_029', 'subj_wassce_crs', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_crs_2023_1', 'Which judge defeated the Midianites with only 300 men?', 'multiple_choice', '["A. Samson", "B. Gideon", "C. Deborah", "D. Jephthah"]', 'B', 'Gideon defeated the Midianites with only 300 men using torches and trumpets (Judges 7).', 'medium', 1, 29),
('q_crs_2023_030', 'subj_wassce_crs', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_crs_2023_1', 'Who was the only female judge mentioned in the Bible?', 'multiple_choice', '["A. Ruth", "B. Deborah", "C. Esther", "D. Hannah"]', 'B', 'Deborah was the only female judge in Israel, who led alongside Barak (Judges 4-5).', 'easy', 1, 30),

-- Kings and Prophets (Questions 31-40)
('q_crs_2023_031', 'subj_wassce_crs', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_crs_2023_1', 'Samuel was dedicated to God''s service by his mother:', 'multiple_choice', '["A. Sarah", "B. Hannah", "C. Rachel", "D. Rebekah"]', 'B', 'Hannah dedicated Samuel to God''s service at the tabernacle in Shiloh after God answered her prayer for a son (1 Samuel 1).', 'easy', 1, 31),
('q_crs_2023_032', 'subj_wassce_crs', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_crs_2023_1', 'King Saul disobeyed God by:', 'multiple_choice', '["A. Taking a census", "B. Committing adultery", "C. Sparing King Agag and the best animals", "D. Building a temple"]', 'C', 'Saul disobeyed God by not completely destroying the Amalekites; he spared King Agag and the best livestock (1 Samuel 15).', 'medium', 1, 32),
('q_crs_2023_033', 'subj_wassce_crs', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_crs_2023_1', 'David was the son of:', 'multiple_choice', '["A. Saul", "B. Jesse", "C. Samuel", "D. Jonathan"]', 'B', 'David was the son of Jesse of Bethlehem, the youngest of eight brothers (1 Samuel 16:10-11).', 'easy', 1, 33),
('q_crs_2023_034', 'subj_wassce_crs', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_crs_2023_1', 'Who was David''s best friend?', 'multiple_choice', '["A. Solomon", "B. Absalom", "C. Jonathan", "D. Nathan"]', 'C', 'Jonathan, son of King Saul, was David''s closest friend. They made a covenant of friendship (1 Samuel 18:1-4).', 'easy', 1, 34),
('q_crs_2023_035', 'subj_wassce_crs', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_crs_2023_1', 'Solomon built the first temple in:', 'multiple_choice', '["A. Bethlehem", "B. Nazareth", "C. Jerusalem", "D. Hebron"]', 'C', 'Solomon built the first temple of the Lord in Jerusalem on Mount Moriah (2 Chronicles 3:1).', 'easy', 1, 35),
('q_crs_2023_036', 'subj_wassce_crs', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_crs_2023_1', 'The wicked queen who promoted Baal worship in Israel was:', 'multiple_choice', '["A. Esther", "B. Jezebel", "C. Athaliah", "D. Bathsheba"]', 'B', 'Jezebel, wife of King Ahab, promoted Baal worship and persecuted the prophets of God (1 Kings 16:31, 18:4).', 'medium', 1, 36),
('q_crs_2023_037', 'subj_wassce_crs', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_crs_2023_1', 'Naaman was healed of leprosy by washing in the River:', 'multiple_choice', '["A. Nile", "B. Euphrates", "C. Jordan", "D. Tigris"]', 'C', 'Elisha told Naaman to wash seven times in the Jordan River, and he was healed of leprosy (2 Kings 5:10-14).', 'easy', 1, 37),
('q_crs_2023_038', 'subj_wassce_crs', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_crs_2023_1', 'Which empire conquered Judah and destroyed the temple?', 'multiple_choice', '["A. Assyria", "B. Babylon", "C. Persia", "D. Greece"]', 'B', 'The Babylonian Empire under Nebuchadnezzar conquered Judah in 586 BC and destroyed Solomon''s temple (2 Kings 25).', 'medium', 1, 38),
('q_crs_2023_039', 'subj_wassce_crs', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_crs_2023_1', 'Ezra was a:', 'multiple_choice', '["A. King", "B. Priest and scribe", "C. Prophet", "D. Judge"]', 'B', 'Ezra was a priest and scribe who led a group of exiles back to Jerusalem and taught the law (Ezra 7:6, 10).', 'medium', 1, 39),
('q_crs_2023_040', 'subj_wassce_crs', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_crs_2023_1', 'Who rebuilt the walls of Jerusalem?', 'multiple_choice', '["A. Ezra", "B. Nehemiah", "C. Zerubbabel", "D. Haggai"]', 'B', 'Nehemiah led the project to rebuild the walls of Jerusalem in 52 days (Nehemiah 6:15).', 'medium', 1, 40),

-- New Testament (Questions 41-50)
('q_crs_2023_041', 'subj_wassce_crs', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_crs_2023_1', 'The angel who announced Jesus'' birth to Mary was:', 'multiple_choice', '["A. Michael", "B. Gabriel", "C. Raphael", "D. Uriel"]', 'B', 'The angel Gabriel was sent by God to announce to Mary that she would conceive and bear a son (Luke 1:26-31).', 'easy', 1, 41),
('q_crs_2023_042', 'subj_wassce_crs', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_crs_2023_1', 'The wise men from the East brought gifts of:', 'multiple_choice', '["A. Gold, silver, and bronze", "B. Gold, frankincense, and myrrh", "C. Wheat, wine, and oil", "D. Sheep, goats, and cattle"]', 'B', 'The wise men brought gifts of gold, frankincense, and myrrh to the child Jesus (Matthew 2:11).', 'easy', 1, 42),
('q_crs_2023_043', 'subj_wassce_crs', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_crs_2023_1', 'Where was Jesus when He was twelve years old and His parents found Him teaching?', 'multiple_choice', '["A. The synagogue in Nazareth", "B. The temple in Jerusalem", "C. By the Sea of Galilee", "D. In Bethlehem"]', 'B', 'Jesus'' parents found Him in the temple in Jerusalem, sitting among the teachers (Luke 2:41-50).', 'easy', 1, 43),
('q_crs_2023_044', 'subj_wassce_crs', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_crs_2023_1', 'Jesus called Peter and Andrew while they were:', 'multiple_choice', '["A. Collecting taxes", "B. Fishing", "C. Building boats", "D. Shepherding"]', 'B', 'Jesus called Peter and Andrew while they were fishing, telling them He would make them fishers of men (Matthew 4:18-19).', 'easy', 1, 44),
('q_crs_2023_045', 'subj_wassce_crs', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_crs_2023_1', 'In the Parable of the Good Samaritan, who passed by the injured man first?', 'multiple_choice', '["A. A Samaritan", "B. A priest", "C. A tax collector", "D. A soldier"]', 'B', 'A priest first passed by on the other side, then a Levite, before the Samaritan helped (Luke 10:31-33).', 'easy', 1, 45),
('q_crs_2023_046', 'subj_wassce_crs', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_crs_2023_1', 'The Lord''s Prayer begins with:', 'multiple_choice', '["A. Give us this day our daily bread", "B. Our Father who art in heaven", "C. Forgive us our debts", "D. Lead us not into temptation"]', 'B', 'The Lord''s Prayer begins with "Our Father who art in heaven, hallowed be thy name" (Matthew 6:9).', 'easy', 1, 46),
('q_crs_2023_047', 'subj_wassce_crs', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_crs_2023_1', 'Which disciple denied Jesus three times?', 'multiple_choice', '["A. John", "B. James", "C. Peter", "D. Thomas"]', 'C', 'Peter denied knowing Jesus three times before the rooster crowed, as Jesus had predicted (Matthew 26:69-75).', 'easy', 1, 47),
('q_crs_2023_048', 'subj_wassce_crs', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_crs_2023_1', 'Jesus rose from the dead on the:', 'multiple_choice', '["A. First day", "B. Second day", "C. Third day", "D. Fourth day"]', 'C', 'Jesus rose from the dead on the third day, as He had foretold (Matthew 16:21, 1 Corinthians 15:4).', 'easy', 1, 48),
('q_crs_2023_049', 'subj_wassce_crs', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_crs_2023_1', 'The Great Commission commands believers to:', 'multiple_choice', '["A. Build churches", "B. Collect tithes", "C. Make disciples of all nations", "D. Observe the Sabbath"]', 'C', 'The Great Commission commands believers to go and make disciples of all nations, baptizing and teaching them (Matthew 28:19-20).', 'easy', 1, 49),
('q_crs_2023_050', 'subj_wassce_crs', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_crs_2023_1', 'The first Christian martyr was:', 'multiple_choice', '["A. Peter", "B. Paul", "C. Stephen", "D. James"]', 'C', 'Stephen was the first Christian martyr, stoned to death for his faith (Acts 7:54-60).', 'medium', 1, 50);
